using System;using System.IO;using System.Linq;using UnityEngine;using UnityEditor;using Newtonsoft.Json;
public static class BFFCatalog {public static object Run(){AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);string repo=Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));string path="Assets/Afrer_Seconds/05.Model/Props/B4/";var a=Directory.GetFiles(Path.Combine(Application.dataPath,"..",path),"BF_*.fbx").Select(f=>{string p=path+Path.GetFileName(f);var g=AssetDatabase.LoadAssetAtPath<GameObject>(p);var rs=g.GetComponentsInChildren<Renderer>();var b=rs[0].bounds;foreach(var r in rs.Skip(1))b.Encapsulate(r.bounds);return new{asset=p,name=Path.GetFileNameWithoutExtension(p),size=new[]{b.size.x,b.size.y,b.size.z},center=new[]{b.center.x,b.center.y,b.center.z}};}).ToArray();File.WriteAllText(repo+"/SourceAssets/B4_FullFloor/new_catalog.json",JsonConvert.SerializeObject(a,Formatting.Indented));return new{assets=a.Length};}}
